def print_table(table, indent_level=0):
    indent = "  " * indent_level
    print(f"{indent}Table with {len(table.rows)} rows:")
    for r_idx, row in enumerate(table.rows):
        print(f"{indent}  Row {r_idx}:")
        for c_idx, cell in enumerate(row.cells):
            cell_text = " | ".join([p.text for p in cell.paragraphs])
            print(f"{indent}    Cell ({r_idx},{c_idx}): [{cell_text}]")
            if cell.tables:
                print(f"{indent}    [Found {len(cell.tables)} nested tables in cell ({r_idx},{c_idx})]")
                for nested in cell.tables:
                    print_table(nested, indent_level + 2)

